package dev.perf.cli.command

import com.github.ajalt.clikt.core.CliktCommand
import com.github.ajalt.clikt.core.ProgramResult
import com.github.ajalt.clikt.parameters.options.flag
import com.github.ajalt.clikt.parameters.options.option
import dev.perf.cli.BuildConfig
import dev.perf.guardian.GuardianAssets
import dev.perf.trace.QueryPackLoader
import kotlinx.serialization.SerializationException

/**
 * `perf version` — print the installed perf CLI version.
 *
 * The version is resolved at compile time from [BuildConfig.VERSION]
 * (a `const val` generated by the Gradle `generateBuildConfig` task).
 * No reflection or classpath access is required — safe for GraalVM native image.
 *
 * Also carries a hidden `--verify-resources` flag — see [verifyEmbeddedResources].
 */
class VersionCommand : CliktCommand(
    name = "version",
    help = "Print the installed perf CLI version.",
) {
    private val verifyResources: Boolean by option(
        "--verify-resources",
        hidden = true,
        help = "Open every embedded guardian + query-pack classpath resource; exit 1 on any miss.",
    ).flag()

    override fun run() {
        if (verifyResources) {
            verifyEmbeddedResources()
            return
        }
        echo(BuildConfig.VERSION)
    }

    /**
     * Native-image resource reachability spike (`sdd/android-agent-guardian` PR1, GI-7):
     * opens every classpath resource referenced by the guardian catalog and the
     * query-pack manifest, printing a hit/miss report, and exits 1 on any miss.
     *
     * CI's `native-smoke` job runs `:app:nativeCompile` then `perf version --verify-resources`
     * against the compiled `--no-fallback` binary — if resource-config.json patterns are wrong,
     * this is where it is caught, with an actionable report instead of a silent miss.
     *
     * Both [GuardianAssets.loadCatalog] (via [GuardianAssets.catalogResourcePaths]) and
     * [QueryPackLoader.loadV1] (via [queryPackResourcePaths]) throw [IllegalStateException]
     * (`error(...)`) when their own manifest.json is unreachable, and [SerializationException]
     * when it is reachable but malformed (e.g. a required field with the wrong JSON type) — that
     * must not crash this command uncaught; [loadCatalogChecks]/[loadQueryPackChecks] catch both
     * and report a graceful MISS for the relevant manifest path instead (PR1 review findings #1
     * and, on the second pass, #2 — [SerializationException] extends [IllegalArgumentException],
     * not [IllegalStateException], so the original fix did not cover it).
     */
    private fun verifyEmbeddedResources() {
        val exists = GuardianAssets::resourceExists
        val results =
            loadCatalogChecks(GuardianAssets.MANIFEST_PATH, exists) { GuardianAssets.catalogResourcePaths() } +
                loadQueryPackChecks(QueryPackLoader.MANIFEST_PATH, exists) { queryPackResourcePaths() }

        results.forEach { check ->
            echo("${if (check.found) "OK  " else "MISS"} ${check.path}")
        }

        val missCount = results.count { !it.found }
        if (missCount > 0) {
            echo("$missCount of ${results.size} embedded resources missing.")
            throw ProgramResult(1)
        }
        echo("All ${results.size} embedded resources reachable.")
    }

    private fun queryPackResourcePaths(): List<String> {
        val manifest = QueryPackLoader.loadV1()
        val paths = mutableListOf(QueryPackLoader.MANIFEST_PATH)
        manifest.domains.values.forEach { spec ->
            spec.queryResource?.let { paths += "/query-packs/v1/$it" }
        }
        return paths
    }
}

/** One classpath resource path and whether it was reachable. */
internal data class ResourceCheck(val path: String, val found: Boolean)

/**
 * Pure core of `--verify-resources`: checks each of [paths] against [exists] and reports
 * hit/miss per path, preserving input order. No classpath I/O of its own — [exists] is
 * injected so the miss-detection algorithm is testable without deleting real resources.
 */
internal fun verifyResourcePaths(paths: List<String>, exists: (String) -> Boolean): List<ResourceCheck> =
    paths.map { path -> ResourceCheck(path, exists(path)) }

/**
 * Loads the guardian catalog's resource paths via [loadPaths] (normally
 * `GuardianAssets.catalogResourcePaths()`) and checks each against [exists].
 *
 * Review findings addressed here:
 * - **Finding #1 (correctness)**: [loadPaths] can throw [IllegalStateException] when the
 *   catalog's own manifest.json is unreachable (`GuardianAssets.loadCatalog()` calls
 *   `error(...)`). That must be reported as a graceful MISS for [manifestPath], not crash
 *   `--verify-resources` uncaught.
 * - **Finding #2 (second pass, correctness)**: [loadPaths] can also throw
 *   [SerializationException] when the manifest.json is reachable but malformed (e.g. a
 *   required field with the wrong JSON type). [SerializationException] extends
 *   [IllegalArgumentException], not [IllegalStateException], so it needs its own catch clause —
 *   it must be reported the same way, as a graceful MISS for [manifestPath].
 * - **Finding #6 (efficiency)**: when [loadPaths] succeeds, its first entry is always the
 *   manifest path itself (see `GuardianAssets.resourcePathsFor`) — a successful catalog
 *   parse already proves that path is reachable, so it is marked found without a second
 *   [exists] call that would reopen the same classpath resource.
 */
internal fun loadCatalogChecks(
    manifestPath: String,
    exists: (String) -> Boolean,
    loadPaths: () -> List<String>,
): List<ResourceCheck> {
    val paths = try {
        loadPaths()
    } catch (e: IllegalStateException) {
        return listOf(ResourceCheck(manifestPath, found = false))
    } catch (e: SerializationException) {
        return listOf(ResourceCheck(manifestPath, found = false))
    }
    if (paths.isEmpty()) return emptyList()
    val provenManifestCheck = ResourceCheck(paths.first(), found = true)
    return listOf(provenManifestCheck) + verifyResourcePaths(paths.drop(1), exists)
}

/**
 * Loads the query-pack manifest's resource paths via [loadPaths] (normally
 * `queryPackResourcePaths()`, backed by `QueryPackLoader.loadV1()`) and checks each against
 * [exists]. Mirrors [loadCatalogChecks] exactly:
 * - **Finding #1 / #2 (correctness)**: `QueryPackLoader.loadV1()` also throws
 *   [IllegalStateException] via `error(...)` when its manifest.json is missing, and
 *   [SerializationException] when it is reachable but malformed — both must be reported as a
 *   graceful MISS for [manifestPath] instead of crashing `--verify-resources` uncaught.
 * - **Finding #4 (efficiency, second pass — mirrors finding #6)**: when [loadPaths] succeeds,
 *   its first entry is always the manifest path itself (see `VersionCommand.queryPackResourcePaths`)
 *   — a successful `loadV1()` parse already proves that path is reachable, so it is marked found
 *   without a second [exists] call that would reopen the same classpath resource.
 */
internal fun loadQueryPackChecks(
    manifestPath: String,
    exists: (String) -> Boolean,
    loadPaths: () -> List<String>,
): List<ResourceCheck> {
    val paths = try {
        loadPaths()
    } catch (e: IllegalStateException) {
        return listOf(ResourceCheck(manifestPath, found = false))
    } catch (e: SerializationException) {
        return listOf(ResourceCheck(manifestPath, found = false))
    }
    if (paths.isEmpty()) return emptyList()
    val provenManifestCheck = ResourceCheck(paths.first(), found = true)
    return listOf(provenManifestCheck) + verifyResourcePaths(paths.drop(1), exists)
}
